mainContent:
/**
 * Main Entry Point
 *
 * Vanilla JS Core XML CRDT Demo
 * Initializes Velt client, user, document, and renders the UI.
 */

// Import styles
import '../styles/globals.css';
// [Velt] Import Velt UI customization styles
import './components/velt/ui-customization/styles.css';

// Import modules
import { initializeUser } from './lib/user.js';
import { initializeDocument } from './lib/document.js';
import { initializeTheme } from './lib/theme.js';
// [Velt] Import Velt client helpers
import {
  initializeVelt,
  authenticateUser,
  setVeltDocument,
} from './lib/velt.js';
import { createDocumentCanvas } from './components/document/document-canvas.js';
// [Velt] Import Velt collaboration components
import { configureNotificationsTool } from './components/velt/velt-tools.js';
import { createMindMapEditor } from './components/document/mind-map/mind-map-editor.js';
import { createVeltCollaboration } from './components/velt/velt-collaboration.js';

// App state
let documentCanvas = null;
let editorInstance = null;

/**
 * Wait for Velt to be fully initialized (user + document synced)
 * @param {Object} veltClient - Velt client instance
 * @param {number} timeout - Timeout in milliseconds (default 30s)
 * @returns {Promise<boolean>}
 */
function waitForVeltInitState(veltClient, timeout = 30000) {
  return new Promise((resolve) => {
    const startTime = Date.now();

    const subscription = veltClient.getVeltInitState().subscribe((state) => {
      console.log('[App] Velt init state:', state);

      if (state === true) {
        subscription?.unsubscribe();
        resolve(true);
        return;
      }

      if (Date.now() - startTime > timeout) {
        subscription?.unsubscribe();
        console.warn('[App] Velt init state timeout, proceeding anyway');
        resolve(false);
      }
    });

    setTimeout(() => {
      subscription?.unsubscribe();
      console.warn('[App] Velt init state timeout (fallback), proceeding anyway');
      resolve(false);
    }, timeout);
  });
}

/**
 * Initialize the application
 */
async function init() {
  console.log('[App] Starting initialization...');

  const app = document.getElementById('app');
  if (!app) {
    console.error('[App] No #app element found');
    return;
  }

  // Show loading state
  app.innerHTML = `
    <div class="flex items-center justify-center h-screen w-screen" style="background-color: var(--app-bg);">
      <div style="color: var(--app-text-primary);" class="text-center">
        <div class="mb-4">
          <div class="animate-spin rounded-full h-8 w-8 border-b-2 border-current mx-auto"></div>
        </div>
        <p>Initializing collaboration...</p>
      </div>
    </div>
  `;

  try {
    // Step 1: Initialize user
    console.log('[App] Step 1: Initializing user...');
    const user = initializeUser();
    if (!user) throw new Error('Failed to initialize user');
    console.log('[App] User initialized:', user.name);

    // Step 2: Initialize document
    console.log('[App] Step 2: Initializing document...');
    const doc = initializeDocument();
    if (!doc.documentId) throw new Error('Failed to initialize document');
    console.log('[App] Document initialized:', doc.documentId);

    // [Velt] Step 3: Initialize Velt client
    console.log('[App] Step 3: Initializing Velt client...');
    const veltClient = await initializeVelt();
    if (!veltClient) throw new Error('Failed to initialize Velt client');

    // [Velt] Step 4: Authenticate user with Velt
    console.log('[App] Step 4: Authenticating user with Velt...');
    await authenticateUser(user);

    // [Velt] Step 5: Set document scope in Velt
    console.log('[App] Step 5: Setting document in Velt...');
    await setVeltDocument(doc.documentId, doc.documentName);

    // Step 6: Initialize theme system
    console.log('[App] Step 6: Initializing theme...');
    initializeTheme();

    // [Velt] Step 7: Configure notifications
    console.log('[App] Step 7: Configuring notifications...');
    configureNotificationsTool(veltClient);

    // Clear loading state
    app.innerHTML = '';

    // Step 8: Create main layout
    console.log('[App] Step 8: Creating main layout...');
    const mainContainer = document.createElement('main');
    mainContainer.className = 'w-full h-screen relative';
    app.appendChild(mainContainer);

    documentCanvas = createDocumentCanvas(mainContainer);

    // [Velt] Step 9: Wait for Velt SDK to be ready before creating editor
    console.log('[App] Step 9: Waiting for Velt init state...');
    await waitForVeltInitState(veltClient);
    console.log('[App] Velt fully initialized, creating editor...');

    const editorContainer = documentCanvas.editorContainer;
    if (editorContainer) {
      editorInstance = await createMindMapEditor(editorContainer, veltClient, user);
      console.log('[App] Editor created successfully');
    }

    // [Velt] Add Velt collaboration components (comments, sidebar)
    createVeltCollaboration(app);

    console.log('[App] Initialization complete!');
  } catch (error) {
    console.error('[App] Initialization failed:', error);
    app.innerHTML = `
      <div class="flex items-center justify-center h-screen w-screen" style="background-color: var(--app-bg);">
        <div class="text-center" style="color: var(--app-text-tertiary);">
          <p class="text-xl mb-2" style="color: #ef4444;">Failed to initialize</p>
          <p class="opacity-70">${error.message}</p>
          <button
            onclick="window.location.reload()"
            class="mt-4 px-4 py-2 rounded"
            style="background-color: var(--app-toggle-active-bg); color: var(--app-text-primary);"
          >
            Retry
          </button>
        </div>
      </div>
    `;
  }
}

/**
 * Cleanup on page unload
 */
function cleanup() {
  if (editorInstance && editorInstance.destroy) editorInstance.destroy();
  if (documentCanvas && documentCanvas.destroy) documentCanvas.destroy();
}

window.addEventListener('beforeunload', cleanup);

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

veltContent:
/**
 * Velt Client Initialization Module
 *
 * Uses @veltdev/client for vanilla JavaScript initialization.
 */

// [Velt] Import Velt client SDK
import { initVelt } from '@veltdev/client';

// [Velt] Replace with your own API key from https://console.velt.dev
const VELT_API_KEY = '6xTcUFtlYAlCdh11zrKB';
const VELT_AUTH_TOKEN = 'bd4d5226050470b6c658054fcdf1092a';

let veltClient = null;
let veltInitialized = false;
const initListeners = [];

/**
 * Get Velt client instance
 * @returns {Object|null} - Velt client or null
 */
export function getVeltClient() {
  return veltClient;
}

/**
 * Check if Velt is initialized
 * @returns {boolean} - Initialization state
 */
export function isVeltInitialized() {
  return veltInitialized;
}

/**
 * Subscribe to Velt initialization
 * @param {Function} callback - Callback function
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToVeltInit(callback) {
  initListeners.push(callback);
  // Call immediately if already initialized
  if (veltInitialized) {
    callback(veltClient);
  }
  return () => {
    const index = initListeners.indexOf(callback);
    if (index > -1) {
      initListeners.splice(index, 1);
    }
  };
}

/**
 * Notify all listeners of initialization
 */
function notifyInitListeners() {
  initListeners.forEach(callback => callback(veltClient));
}

/**
 * Generate JWT token from Velt API
 * @param {Object} user - User object with userId, organizationId, email
 * @returns {Promise<string>} - JWT token
 */
async function generateVeltToken(user) {
  const body = {
    data: {
      userId: user.userId,
      userProperties: {
        organizationId: user.organizationId,
        email: user.email || undefined,
      },
    },
  };

  const response = await fetch('https://api.velt.dev/v2/auth/token/get', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-velt-api-key': VELT_API_KEY,
      'x-velt-auth-token': VELT_AUTH_TOKEN,
    },
    body: JSON.stringify(body),
  });

  const json = await response.json();
  const token = json?.result?.data?.token;

  if (!response.ok || !token) {
    throw new Error(json?.error?.message || 'Failed to generate token');
  }

  return token;
}

/**
 * Initialize Velt client
 * @returns {Promise<Object>} - Velt client
 */
export async function initializeVelt() {
  if (veltClient) {
    return veltClient;
  }

  try {
    // [Velt] Initialize Velt client
    veltClient = await initVelt(VELT_API_KEY);
    console.log('[Velt] Client initialized');
    return veltClient;
  } catch (error) {
    console.error('[Velt] Failed to initialize client:', error);
    throw error;
  }
}

/**
 * Authenticate user with Velt
 * @param {Object} user - User object
 * @returns {Promise<void>}
 */
export async function authenticateUser(user) {
  if (!veltClient) {
    throw new Error('Velt client not initialized');
  }

  if (!user) {
    throw new Error('User is required');
  }

  try {
    // Generate JWT token for secure authentication
    const token = await generateVeltToken(user);

    // [Velt] Identify user with JWT token
    await veltClient.identify(user, {
      authToken: token,
    });

    console.log('[Velt] User authenticated:', user.name);
  } catch (error) {
    console.error('[Velt] Failed to authenticate user:', error);
    // Fallback to simple identify without token (for demo purposes)
    try {
      await veltClient.identify(user);
      console.log('[Velt] User authenticated (without token):', user.name);
    } catch (fallbackError) {
      console.error('[Velt] Fallback authentication failed:', fallbackError);
      throw fallbackError;
    }
  }
}

/**
 * Set document in Velt
 * @param {string} documentId - Document ID
 * @param {string} documentName - Document name
 * @returns {Promise<void>}
 */
export async function setVeltDocument(documentId, documentName = 'Untitled') {
  if (!veltClient) {
    throw new Error('Velt client not initialized');
  }

  try {
    // [Velt] Set document scope
    await veltClient.setDocument(documentId, {
      documentName: documentName,
    });
    console.log('[Velt] Document set:', documentId);
  } catch (error) {
    console.error('[Velt] Failed to set document:', error);
    throw error;
  }
}

/**
 * Enable dark mode
 */
export function enableDarkMode() {
  if (veltClient) {
    // [Velt] Enable dark mode
    veltClient.setDarkMode(true);
  }
}

/**
 * Set Velt dark mode
 * @param {boolean} isDark - Whether to enable dark mode
 */
export function setVeltDarkMode(isDark) {
  if (veltClient) {
    // [Velt] Toggle dark mode
    veltClient.setDarkMode(isDark);
  }
}

/**
 * Sign out user
 */
export async function signOutUser() {
  if (veltClient) {
    try {
      // [Velt] Sign out user
      await veltClient.signOutUser();
      console.log('[Velt] User signed out');
    } catch (error) {
      console.error('[Velt] Failed to sign out user:', error);
    }
  }
}

/**
 * Mark Velt as fully initialized (user + document set)
 */
export function markVeltInitialized() {
  veltInitialized = true;
  notifyInitListeners();
}

/**
 * Subscribe to Velt init state
 * @param {Function} callback - Callback function receiving boolean
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToVeltInitState(callback) {
  if (!veltClient) {
    callback(false);
    return () => {};
  }

  const subscription = veltClient.getVeltInitState().subscribe((state) => {
    callback(state === true);
  });

  return () => {
    subscription?.unsubscribe();
  };
}

userContent:
/**
 * User Management Module
 *
 * This user authentication logic is ONLY for demo purposes.
 */

const STORAGE_KEY = 'core-crdt-demo-user';

const avatarColors = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2'];
const firstNames = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Casey', 'Morgan', 'Riley', 'Avery'];
const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis'];

function hashStringToIndex(str, arrayLength) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash) % arrayLength;
}

function hashString(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(36).padStart(8, '0');
}

function generateRandomUser() {
  const firstName = firstNames[Math.floor(Math.random() * firstNames.length)];
  const lastName = lastNames[Math.floor(Math.random() * lastNames.length)];
  const fullName = `${firstName} ${lastName}`;
  const userId = `user-${hashString(fullName)}`;
  const colorIndex = hashStringToIndex(userId, avatarColors.length);
  const avatarColor = avatarColors[colorIndex];

  return {
    userId,
    name: fullName,
    email: `${firstName.toLowerCase()}.${lastName.toLowerCase()}@example.com`,
    organizationId: 'sample-apps-demo-org',
    photoUrl: `https://ui-avatars.com/api/?name=${encodeURIComponent(fullName)}&background=${avatarColor.substring(1)}&color=fff&size=128`,
  };
}

function getStorage() {
  try {
    const isInIframe = window.self !== window.top;
    return isInIframe ? sessionStorage : localStorage;
  } catch {
    return localStorage;
  }
}

let currentUser = undefined;
let isUserLoggedIn = undefined;
const userListeners = [];

export function getUser() { return currentUser; }
export function getIsUserLoggedIn() { return isUserLoggedIn; }

export function subscribeToUser(callback) {
  userListeners.push(callback);
  callback(currentUser, isUserLoggedIn);
  return () => {
    const index = userListeners.indexOf(callback);
    if (index > -1) userListeners.splice(index, 1);
  };
}

function notifyListeners() {
  userListeners.forEach(callback => callback(currentUser, isUserLoggedIn));
}

export function initializeUser() {
  try {
    const storage = getStorage();
    const stored = storage.getItem(STORAGE_KEY);
    if (stored) {
      currentUser = JSON.parse(stored);
    } else {
      currentUser = generateRandomUser();
      storage.setItem(STORAGE_KEY, JSON.stringify(currentUser));
    }
    isUserLoggedIn = true;
    notifyListeners();
    return currentUser;
  } catch {
    return undefined;
  }
}

export function login(user) {
  try {
    const storage = getStorage();
    currentUser = user;
    isUserLoggedIn = true;
    storage.setItem(STORAGE_KEY, JSON.stringify(user));
    notifyListeners();
  } catch {}
}

export function logout() {
  try {
    const storage = getStorage();
    currentUser = undefined;
    isUserLoggedIn = false;
    storage.removeItem(STORAGE_KEY);
    notifyListeners();
  } catch {}
}

documentContent:
/**
 * Document Management Module
 */

const STORAGE_KEY = 'core-xml-crdt-document-id';

let documentId = null;
let isInitialized = false;

export function getCurrentDocument() {
  return { documentId, documentName: 'My Document' };
}

export function initializeDocument() {
  if (isInitialized) return getCurrentDocument();

  const urlParams = new URLSearchParams(window.location.search);
  let docId = urlParams.get('documentId');

  if (docId) {
    documentId = docId;
    localStorage.setItem(STORAGE_KEY, docId);
  } else {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      docId = stored;
    } else {
      docId = `doc-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
      localStorage.setItem(STORAGE_KEY, docId);
    }
    const newUrl = `${window.location.pathname}?documentId=${docId}`;
    window.history.pushState({}, '', newUrl);
    documentId = docId;
  }

  isInitialized = true;
  return getCurrentDocument();
}

export function getDocumentId() { return documentId; }

themeContent:
/**
 * Theme Management Module
 *
 * Theme Management Module
 *
 * Manages light/dark/system theme state and persistence.
 * Supports light, dark, and system themes with URL param override and postMessage sync.
 */

import { setVeltDarkMode } from './velt.js';

const STORAGE_KEY = 'theme-preference';

let currentTheme = 'light';
let resolvedTheme = 'light';
const themeListeners = [];

/**
 * Get system theme preference
 * @returns {'light'|'dark'} - System theme
 */
function getSystemTheme() {
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/**
 * Resolve a theme value to light or dark
 * @param {'light'|'dark'|'system'} theme - Theme value
 * @returns {'light'|'dark'} - Resolved theme
 */
function resolveThemeValue(theme) {
  if (theme === 'system') return getSystemTheme();
  return theme;
}

/**
 * Apply theme to the DOM
 * @param {'light'|'dark'} resolved - Resolved theme
 */
function applyTheme(resolved) {
  if (resolved === 'dark') {
    document.documentElement.classList.add('dark');
  } else {
    document.documentElement.classList.remove('dark');
  }
  // Sync Velt dark mode
  setVeltDarkMode(resolved === 'dark');
}

/**
 * Read theme from URL ?theme= param
 * @returns {'light'|'dark'|'system'|null}
 */
function getUrlTheme() {
  const params = new URLSearchParams(window.location.search);
  const t = params.get('theme');
  if (t === 'light' || t === 'dark' || t === 'system') return t;
  return null;
}

/**
 * Get initial theme from URL or localStorage
 * @returns {'light'|'dark'|'system'}
 */
function getInitialTheme() {
  return getUrlTheme() || localStorage.getItem(STORAGE_KEY) || 'light';
}

/**
 * Notify all theme listeners
 */
function notifyListeners() {
  themeListeners.forEach(callback => callback(resolvedTheme, currentTheme));
}

/**
 * Get current resolved theme
 * @returns {'light'|'dark'}
 */
export function getResolvedTheme() {
  return resolvedTheme;
}

/**
 * Get current theme setting
 * @returns {'light'|'dark'|'system'}
 */
export function getTheme() {
  return currentTheme;
}

/**
 * Set theme
 * @param {'light'|'dark'|'system'} theme - Theme to set
 */
export function setTheme(theme) {
  currentTheme = theme;
  localStorage.setItem(STORAGE_KEY, theme);
  resolvedTheme = resolveThemeValue(theme);
  applyTheme(resolvedTheme);
  notifyListeners();
}

/**
 * Subscribe to theme changes
 * @param {Function} callback - Callback receiving (resolvedTheme, theme)
 * @returns {Function} - Unsubscribe function
 */
export function subscribeToTheme(callback) {
  themeListeners.push(callback);
  // Call immediately with current state
  callback(resolvedTheme, currentTheme);
  return () => {
    const index = themeListeners.indexOf(callback);
    if (index > -1) {
      themeListeners.splice(index, 1);
    }
  };
}

/**
 * Initialize theme system
 * Sets up listeners for postMessage and system preference changes.
 */
export function initializeTheme() {
  // Set initial theme
  currentTheme = getInitialTheme();
  resolvedTheme = resolveThemeValue(currentTheme);
  applyTheme(resolvedTheme);

  // Listen for postMessage from master app for live theme switching
  window.addEventListener('message', (event) => {
    if (event.data?.type === 'theme-change' && event.data.theme) {
      setTheme(event.data.theme);
    }
  });

  // Listen for system preference changes when theme is 'system'
  const mq = window.matchMedia('(prefers-color-scheme: dark)');
  mq.addEventListener('change', () => {
    if (currentTheme === 'system') {
      resolvedTheme = getSystemTheme();
      applyTheme(resolvedTheme);
      notifyListeners();
    }
  });
}

mindMapEditorContent:
/**
 * Mind Map Editor Component with Velt CRDT
 *
 * Vanilla JS implementation using createVeltStore from @veltdev/crdt
 * for real-time collaborative XML tree editing with live focus indicators.
 */

// [Velt] Import CRDT store factory for XML collaboration
import { createVeltStore } from '@veltdev/crdt'
import * as Y from 'yjs'
import { STORE_ID, CURSOR_COLORS, populateInitialContent, storeItems } from './constants.js'
import { createMindMapSidebar } from './mind-map-sidebar.js'

// Layout constants
const NODE_H = 43
const NODE_GAP_H = 15
const NODE_GAP_V = 70
const NODE_PAD = 32
const NODE_ICONS_W = 56

function hashToIndex(str, len) {
  let hash = 0
  for (let i = 0; i < str.length; i++) { hash = ((hash << 5) - hash) + str.charCodeAt(i); hash = hash & hash }
  return Math.abs(hash) % len
}

function generateId() { return `n-${Date.now()}-${Math.random().toString(36).substring(2, 7)}` }

function xmlToTree(container) {
  const nodes = []
  for (let i = 0; i < container.length; i++) {
    const child = container.get(i)
    if (child instanceof Y.XmlElement) {
      nodes.push({ id: child.getAttribute('id') || '', text: child.getAttribute('text') || '', children: xmlToTree(child) })
    }
  }
  return nodes
}

function findElementById(container, id) {
  for (let i = 0; i < container.length; i++) {
    const child = container.get(i)
    if (child instanceof Y.XmlElement) {
      if (child.getAttribute('id') === id) return child
      const found = findElementById(child, id)
      if (found) return found
    }
  }
  return null
}

function findElementWithParent(container, id) {
  for (let i = 0; i < container.length; i++) {
    const child = container.get(i)
    if (child instanceof Y.XmlElement) {
      if (child.getAttribute('id') === id) return { parent: container, index: i }
      const found = findElementWithParent(child, id)
      if (found) return found
    }
  }
  return null
}

function measureText(text) { return Math.max(120, text.length * 9.6 + NODE_PAD + NODE_ICONS_W) }

function layoutTree(node, centerX, y) {
  const positions = new Map()
  const nodeW = measureText(node.text)
  if (node.children.length === 0) {
    positions.set(node.id, { x: centerX - nodeW / 2, y, w: nodeW })
    return { width: nodeW, height: NODE_H, positions }
  }
  const childLayouts = node.children.map(c => layoutTree(c, 0, 0))
  const totalChildrenWidth = childLayouts.reduce((sum, cl) => sum + cl.width, 0) + (node.children.length - 1) * NODE_GAP_H
  positions.set(node.id, { x: centerX - nodeW / 2, y, w: nodeW })
  const childY = y + NODE_H + NODE_GAP_V
  let childStartX = centerX - totalChildrenWidth / 2
  for (let i = 0; i < node.children.length; i++) {
    const cl = childLayouts[i]
    const childCenterX = childStartX + cl.width / 2
    const repositioned = layoutTree(node.children[i], childCenterX, childY)
    for (const [k, v] of repositioned.positions) positions.set(k, v)
    childStartX += cl.width + NODE_GAP_H
  }
  const maxChildHeight = Math.max(...childLayouts.map(cl => cl.height))
  return { width: Math.max(nodeW, totalChildrenWidth), height: NODE_H + NODE_GAP_V + maxChildHeight, positions }
}

function buildConnectorPath(node, positions) {
  let paths = ''
  const parentPos = positions.get(node.id)
  if (!parentPos || node.children.length === 0) return paths
  const parentBottomX = parentPos.x + parentPos.w / 2
  const parentBottomY = parentPos.y + NODE_H
  const midY = parentBottomY + NODE_GAP_V / 2
  const r = 12
  for (const child of node.children) {
    const childPos = positions.get(child.id)
    if (!childPos) continue
    const childTopX = childPos.x + childPos.w / 2
    const childTopY = childPos.y
    const dx = childTopX - parentBottomX
    let d
    if (Math.abs(dx) < 1) {
      d = `M ${parentBottomX} ${parentBottomY} L ${childTopX} ${childTopY}`
    } else {
      const dir = dx > 0 ? 1 : -1
      const absR = Math.min(r, Math.abs(dx), NODE_GAP_V / 2)
      d = `M ${parentBottomX} ${parentBottomY} L ${parentBottomX} ${midY - absR} Q ${parentBottomX} ${midY}, ${parentBottomX + dir * absR} ${midY} L ${childTopX - dir * absR} ${midY} Q ${childTopX} ${midY}, ${childTopX} ${midY + absR} L ${childTopX} ${childTopY}`
    }
    paths += `<path d="${d}" fill="none" stroke="var(--task-connector)" stroke-width="1"/>`
    paths += buildConnectorPath(child, positions)
  }
  return paths
}

/**
 * Create the mind map CRDT editor
 * @param {HTMLElement} container - Container to mount into
 * @param {Object} veltClient - Velt client instance
 * @param {Object} user - Current user object
 * @returns {Promise<Object>} - Component API with el, destroy
 */
export async function createMindMapEditor(container, veltClient, user) {
  let store = null, storeUnsub = null, liveStateSub = null, annotationSub = null
  let tree = [], editingId = null, selectedStoreId = 'sdk-decision'
  let pan = { x: 0, y: 0 }, zoom = 1, hasFitView = false
  let isPanning = false, lastMouse = { x: 0, y: 0 }
  let remoteFocuses = {}
  let annotationDataByTargetId = {}

  const localUser = { userId: user.userId || 'anonymous', name: user.name || 'Anonymous', color: CURSOR_COLORS[hashToIndex(user.userId || user.name || '', CURSOR_COLORS.length)] }

  // DOM
  const root = document.createElement('div')
  root.style.cssText = 'display:flex;height:100%;font-family:Inter,sans-serif;'

  const sidebarContainer = document.createElement('div')
  root.appendChild(sidebarContainer)
  createMindMapSidebar(sidebarContainer, { userName: user.name || 'S', onSelectStore: (id) => { selectedStoreId = id; renderHeader() } })

  const mainCol = document.createElement('div')
  mainCol.style.cssText = 'flex:1;display:flex;flex-direction:column;overflow:hidden;background:var(--task-bg);'
  root.appendChild(mainCol)

  // Header
  const headerArea = document.createElement('div')
  headerArea.style.cssText = 'padding:24px 40px 16px;flex-shrink:0;'
  mainCol.appendChild(headerArea)
  const statusRow = document.createElement('div')
  statusRow.style.cssText = 'display:flex;align-items:center;gap:6px;margin-bottom:24px;'
  statusRow.innerHTML = '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#eab308;"></span><span style="font-size:12px;color:var(--app-text-tertiary);">Connecting...</span>'
  headerArea.appendChild(statusRow)
  const titleSection = document.createElement('div')
  titleSection.style.cssText = 'display:flex;flex-direction:column;gap:12px;'
  headerArea.appendChild(titleSection)

  // Canvas
  const canvasContainer = document.createElement('div')
  canvasContainer.style.cssText = 'flex:1;position:relative;overflow:hidden;cursor:grab;'
  mainCol.appendChild(canvasContainer)

  // Dot grid
  const dotGrid = document.createElement('div')
  dotGrid.style.cssText = 'position:absolute;inset:0;pointer-events:none;opacity:0.15;'
  canvasContainer.appendChild(dotGrid)

  // SVG
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
  svg.setAttribute('width', '100%')
  svg.setAttribute('height', '100%')
  svg.style.cssText = 'position:absolute;inset:0;overflow:visible;'
  canvasContainer.appendChild(svg)
  const svgGroup = document.createElementNS('http://www.w3.org/2000/svg', 'g')
  svg.appendChild(svgGroup)

  container.appendChild(root)

  // Pan/zoom events
  canvasContainer.onmousedown = (e) => {
    if (e.button !== 0) return
    if (e.target.closest('.mindmap-node') || e.target.closest('button') || e.target.closest('input')) return
    isPanning = true; lastMouse = { x: e.clientX, y: e.clientY }; canvasContainer.style.cursor = 'grabbing'; e.preventDefault()
  }
  canvasContainer.onmousemove = (e) => {
    if (!isPanning) return
    pan.x += e.clientX - lastMouse.x; pan.y += e.clientY - lastMouse.y
    lastMouse = { x: e.clientX, y: e.clientY }
    updateTransform()
  }
  canvasContainer.onmouseup = () => { isPanning = false; canvasContainer.style.cursor = 'grab' }
  canvasContainer.onmouseleave = () => { isPanning = false; canvasContainer.style.cursor = 'grab' }
  canvasContainer.onwheel = (e) => { e.preventDefault(); zoom = Math.min(3, Math.max(0.2, zoom * (e.deltaY > 0 ? 0.95 : 1.05))); updateTransform() }

  function updateTransform() {
    svgGroup.setAttribute('transform', `translate(${pan.x}, ${pan.y}) scale(${zoom})`)
    dotGrid.style.backgroundImage = 'radial-gradient(circle, var(--task-connector) 1px, transparent 1px)'
    dotGrid.style.backgroundSize = `${20 * zoom}px ${20 * zoom}px`
    dotGrid.style.backgroundPosition = `${pan.x % (20 * zoom)}px ${pan.y % (20 * zoom)}px`
  }

  // [Velt] Initialize CRDT XML store
  store = await createVeltStore({ id: STORE_ID, type: 'xml', veltClient })
  if (!store) return { destroy() { root.remove() } }

  const xml = store.getXml()
  if (xml && xml.length === 0) {
    const doc = store.getDoc()
    doc.transact(() => { populateInitialContent(xml) })
  }

  function readTree() {
    if (!store) return
    const x = store.getXml()
    if (!x) return
    tree = xmlToTree(x)
    renderCanvas()
  }

  // [Velt] Subscribe to store changes (local + remote)
  // Skip re-render while editing to avoid destroying the active input
  storeUnsub = store.subscribe(() => {
    const x = store.getXml()
    if (!x) return
    tree = xmlToTree(x)
    if (!editingId) renderCanvas()
  })
  readTree()

  // [Velt] Comment annotations — subscribe to get counts per node
  try {
    const commentElement = veltClient.getCommentElement()
    if (commentElement) {
      annotationSub = commentElement.getAllCommentAnnotations().subscribe((annotations) => {
        const dataMap = {}
        if (annotations && Array.isArray(annotations)) {
          annotations.forEach((annotation) => {
            const targetId = annotation.targetElementId
            if (targetId) {
              if (!dataMap[targetId]) dataMap[targetId] = { count: 0, hasUnread: false }
              if (annotation.status?.id !== 'RESOLVED') dataMap[targetId].count = annotation.comments?.length || 0
              if (annotation.unread) dataMap[targetId].hasUnread = true
            }
          })
        }
        annotationDataByTargetId = dataMap
        renderCanvas()
      })
    }
  } catch (e) { console.warn('[MindMapEditor] Comment annotations not available:', e) }

  // [Velt] Live focus — broadcast and subscribe to per-user node focus
  const liveStateElement = veltClient.getLiveStateSyncElement()
  if (liveStateElement) {
    liveStateSub = liveStateElement.getLiveStateData('core-crdt-xml-focuses', { listenToNewChangesOnly: true })
      .subscribe((data) => { remoteFocuses = data || {}; renderCanvas() })
  }

  function broadcastFocus(nodeId) {
    if (!liveStateElement) return
    liveStateElement.setLiveStateData('core-crdt-xml-focuses', {
      ...remoteFocuses, [localUser.userId]: { name: localUser.name, color: localUser.color, nodeId, timestamp: Date.now() }
    })
  }

  // Mutations
  function addChild(parentId) {
    const x = store.getXml()
    if (!x) return
    const parent = findElementById(x, parentId)
    if (!parent) return
    const newId = generateId()
    store.getDoc().transact(() => {
      const el = new Y.XmlElement('node')
      el.setAttribute('id', newId)
      el.setAttribute('text', 'New Node')
      parent.insert(parent.length, [el])
    })
    editingId = newId
  }

  function updateNodeText(nodeId, text) {
    const x = store.getXml()
    if (!x) return
    const el = findElementById(x, nodeId)
    if (!el) return
    store.getDoc().transact(() => { el.setAttribute('text', text) })
  }

  function deleteNode(nodeId) {
    const x = store.getXml()
    if (!x) return
    const result = findElementWithParent(x, nodeId)
    if (!result) return
    store.getDoc().transact(() => { result.parent.delete(result.index, 1) })
  }

  // Find node in tree by ID
  function findNodeById(node, id) {
    if (!node) return null
    if (node.id === id) return node
    for (const child of node.children) {
      const found = findNodeById(child, id)
      if (found) return found
    }
    return null
  }

  // Comment modal
  let commentModal = null
  function showCommentModal(node) {
    if (commentModal) commentModal.remove()
    const targetId = `mindmap-node-${node.id}`
    commentModal = document.createElement('div')
    commentModal.innerHTML = `
      <div class="comment-overlay" style="position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:60;"></div>
      <div class="comment-center" style="position:fixed;inset:0;z-index:70;display:flex;align-items:center;justify-content:center;padding:16px;">
        <div class="comment-box" style="background:var(--task-surface);border-radius:12px;box-shadow:0 25px 50px -12px rgba(0,0,0,0.25);max-width:512px;width:100%;max-height:80vh;display:flex;flex-direction:column;">
          <div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid rgb(229,231,235);">
            <h3 style="font-size:14px;font-weight:600;color:var(--task-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${node.text}</h3>
            <button class="comment-close-btn" style="width:28px;height:28px;display:flex;align-items:center;justify-content:center;border-radius:6px;border:none;background:transparent;cursor:pointer;">
              <svg width="16" height="16" viewBox="0 0 20 20" fill="none"><path d="M15 5L5 15M5 5l10 10" stroke="var(--task-text-secondary)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
            </button>
          </div>
          <div style="flex:1;overflow:auto;" id="${targetId}">
            <!-- [Velt] Inline comments section for this mind-map node -->
            <velt-inline-comments-section target-element-id="${targetId}" shadow-dom="false" composer-position="bottom" multi-thread="false"></velt-inline-comments-section>
          </div>
        </div>
      </div>`
    document.body.appendChild(commentModal)
    commentModal.querySelector('.comment-overlay').onclick = closeCommentModal
    commentModal.querySelector('.comment-center').onclick = closeCommentModal
    commentModal.querySelector('.comment-box').onclick = (e) => e.stopPropagation()
    commentModal.querySelector('.comment-close-btn').onclick = closeCommentModal
  }

  function closeCommentModal() {
    if (commentModal) { commentModal.remove(); commentModal = null }
  }

  // Rendering
  function renderHeader() {
    const item = storeItems.find(s => s.id === selectedStoreId)
    titleSection.innerHTML = `<h1 style="font-size:32px;font-weight:700;line-height:1.2;color:var(--task-text);font-family:Inter,sans-serif;">${item?.name || 'SDK Buying Decision'}</h1><p style="font-size:16px;color:var(--task-text);font-family:Inter,sans-serif;">Pros and cons of using SDK</p>`
  }

  function renderCanvas() {
    const rootNode = tree[0]
    if (!rootNode) { svgGroup.innerHTML = ''; return }

    // Layout at origin, then center
    const raw = layoutTree(rootNode, 0, 0)
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity
    for (const [, pos] of raw.positions) {
      minX = Math.min(minX, pos.x); maxX = Math.max(maxX, pos.x + pos.w)
      minY = Math.min(minY, pos.y); maxY = Math.max(maxY, pos.y + NODE_H)
    }

    // fitView on first render
    if (!hasFitView) {
      const cw = canvasContainer.clientWidth, ch = canvasContainer.clientHeight
      if (cw > 0 && ch > 0) {
        const treeW = maxX - minX, treeH = maxY - minY
        const scaleX = cw / (treeW * 1.3), scaleY = ch / (treeH * 1.3)
        const fitZoom = Math.min(scaleX, scaleY, 1)
        zoom = fitZoom
        pan.x = (cw - treeW * fitZoom) / 2 - minX * fitZoom
        pan.y = (ch - treeH * fitZoom) / 2 - minY * fitZoom
        updateTransform()
        hasFitView = true
      }
    }

    // Build SVG content
    let html = buildConnectorPath(rootNode, raw.positions)
    html += buildNodes(rootNode, raw.positions, true)
    svgGroup.innerHTML = html

    // Attach events to nodes — use JS hover since CSS :hover doesn't work in SVG foreignObject
    svgGroup.querySelectorAll('.mindmap-node').forEach(nodeEl => {
      const nodeId = nodeEl.dataset.nodeId
      nodeEl.onclick = () => broadcastFocus(nodeId)
      nodeEl.ondblclick = () => { editingId = nodeId; renderCanvas() }
      const hoverBtns = nodeEl.querySelectorAll('.mindmap-hover-btn')
      nodeEl.onmouseenter = () => { hoverBtns.forEach(b => b.style.opacity = '1') }
      nodeEl.onmouseleave = () => { hoverBtns.forEach(b => b.style.opacity = '0') }
    })
    svgGroup.querySelectorAll('.node-add-btn').forEach(btn => {
      btn.onclick = (e) => { e.stopPropagation(); addChild(btn.dataset.parentId) }
    })
    svgGroup.querySelectorAll('.node-delete-btn').forEach(btn => {
      btn.onclick = (e) => { e.stopPropagation(); deleteNode(btn.dataset.nodeId) }
    })
    svgGroup.querySelectorAll('.node-comment-btn').forEach(btn => {
      btn.onclick = (e) => {
        e.stopPropagation()
        const nodeId = btn.dataset.nodeId
        const node = findNodeById(tree[0], nodeId)
        if (node) showCommentModal(node)
      }
    })

    // Handle editing inputs
    svgGroup.querySelectorAll('.node-edit-input').forEach(input => {
      const nodeId = input.dataset.nodeId
      input.focus()
      input.select()
      input.oninput = () => { updateNodeText(nodeId, input.value) }
      input.onkeydown = (e) => {
        if (e.key === 'Enter') { editingId = null; renderCanvas() }
        if (e.key === 'Escape') { editingId = null; renderCanvas() }
      }
      input.onclick = (e) => e.stopPropagation()
    })
  }

  function buildNodes(node, positions, isRoot) {
    const pos = positions.get(node.id)
    if (!pos) return ''

    // Remote focus
    let focusUser = null, focusColor = null
    for (const [uid, entry] of Object.entries(remoteFocuses)) {
      if (uid === localUser.userId) continue
      if (Date.now() - (entry.timestamp || 0) > 30000) continue
      if (entry.nodeId === node.id) { focusUser = entry.name; focusColor = entry.color; break }
    }

    const isEditing = editingId === node.id
    const borderStyle = focusColor ? `border:2px solid ${focusColor}` : `border:1px solid var(--task-border)`

    let html = `<foreignObject x="${pos.x}" y="${pos.y - 18}" width="${pos.w}" height="${NODE_H + 18}" style="overflow:visible;">
      <div xmlns="http://www.w3.org/1999/xhtml" style="padding-top:18px;">
        <div id="mindmap-node-${node.id}" class="mindmap-node" data-node-id="${node.id}" style="width:${pos.w}px;height:${NODE_H}px;${borderStyle};">
          ${focusUser ? `<div style="position:absolute;top:-18px;left:4px;font-size:9px;font-weight:600;padding:2px 6px;border-radius:4px;color:white;background:${focusColor};white-space:nowrap;">${focusUser}</div>` : ''}
          ${isEditing
            ? `<input class="node-edit-input" data-node-id="${node.id}" value="${node.text.replace(/"/g, '&quot;')}" style="background:transparent;border:none;outline:none;font-size:16px;width:100%;text-align:center;color:var(--task-text);font-family:Inter,sans-serif;" />`
            : `<span style="flex:1;white-space:nowrap;text-align:center;">${node.text}</span>`
          }
          ${(() => {
            const annot = annotationDataByTargetId[`mindmap-node-${node.id}`]
            const count = annot?.count || 0
            const hasUnread = annot?.hasUnread || false
            const alwaysVisible = count > 0
            return `<button class="node-comment-btn ${alwaysVisible ? '' : 'mindmap-hover-btn'}" data-node-id="${node.id}" style="flex-shrink:0;${alwaysVisible ? 'opacity:1;' : 'opacity:0;'}transition:opacity 0.15s;background:transparent;border:none;cursor:pointer;padding:0;display:flex;align-items:center;gap:2px;">
              <span style="position:relative;display:inline-flex;">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgb(152,152,152)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
                ${hasUnread ? '<span style="position:absolute;top:-2px;right:-2px;width:5px;height:5px;background:#BD323C;border-radius:50%;"></span>' : ''}
              </span>
              ${count > 0 ? `<span style="font-size:9px;font-weight:500;color:rgb(152,152,152);">${count}</span>` : ''}
            </button>`
          })()}
          <button class="node-add-btn mindmap-hover-btn" data-parent-id="${node.id}" style="flex-shrink:0;opacity:0;transition:opacity 0.15s;background:transparent;border:none;cursor:pointer;padding:0;">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="rgb(0,109,220)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="M12 5v14"/></svg>
          </button>
          ${!isRoot ? `<button class="node-delete-btn mindmap-hover-btn" data-node-id="${node.id}" style="flex-shrink:0;opacity:0;transition:opacity 0.15s;background:transparent;border:none;cursor:pointer;padding:0;">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="var(--task-text-secondary)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>
          </button>` : ''}
        </div>
      </div>
    </foreignObject>`

    for (const child of node.children) html += buildNodes(child, positions, false)
    return html
  }

  renderHeader()
  renderCanvas()
  statusRow.innerHTML = '<span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#22c55e;"></span><span style="font-size:12px;color:var(--app-text-tertiary);">Synced</span>'
  updateTransform()

  return {
    el: root,
    destroy() {
      closeCommentModal()
      if (annotationSub) annotationSub.unsubscribe()
      if (storeUnsub) storeUnsub()
      if (liveStateSub) liveStateSub.unsubscribe()
      if (store) store.destroy()
      root.remove()
    },
  }
}

mindMapConstantsContent:
/**
 * Mind Map Constants
 *
 * Store configuration, initial XML tree content, and sidebar store definitions.
 */

import * as Y from 'yjs'

export const STORE_ID = 'core-crdt-xml-mindmap-1'
export const CURSOR_COLORS = ['#FF6B6B', '#4ECDC4', '#45B7D1', '#FFA07A', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E2']

export const storeItems = [
  { id: 'sdk-decision', name: 'SDK Buying Decision' },
  { id: 'design-tasks', name: 'Design Tasks' },
  { id: 'agency-tasks', name: 'Agency Tasks' },
  { id: 'devshop-tasks', name: 'Dev Shop Tasks' },
]

export const storeSections = [
  { header: 'Your Stores', items: ['sdk-decision', 'design-tasks'] },
  { header: 'External', items: ['agency-tasks', 'devshop-tasks'] },
]

function createNode(id, text, children = []) {
  const el = new Y.XmlElement('node')
  el.setAttribute('id', id)
  el.setAttribute('text', text)
  for (const child of children) el.insert(el.length, [child])
  return el
}

export function populateInitialContent(xml) {
  const root = createNode('root', 'Collaborative SDK', [
    createNode('n1', 'Build it in-house', [
      createNode('n1a', 'Requires Money'),
      createNode('n1b', 'Top Talent'),
      createNode('n1c', 'Infrastructure'),
    ]),
    createNode('n2', 'Use Velt SDK', [
      createNode('n2a', 'Ready to use Solutions'),
      createNode('n2b', 'Simple Integrations'),
    ]),
  ])
  xml.insert(0, [root])
}

mindMapSidebarContent:
/**
 * Mind Map Sidebar Component
 *
 * Collapsible sidebar for switching between CRDT stores/documents.
 */

import { storeItems, storeSections } from './constants.js';

/**
 * Create the mind map sidebar
 * @param {HTMLElement} container - Container to append to
 * @param {Object} options - Options
 * @param {string} options.userName - Current user name (for avatar initial)
 * @param {Function} options.onSelectStore - Callback when a store is selected
 * @returns {Object} - Component API with el and destroy
 */
export function createMindMapSidebar(container, { userName = 'S', onSelectStore } = {}) {
  let isCollapsed = true;
  let selectedStoreId = 'sdk-decision';
  let searchQuery = '';

  const el = document.createElement('div');
  el.style.height = '100%';
  el.style.flexShrink = '0';

  function schemaIcon(color) {
    return `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <path d="M4 5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v4a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1z"/>
      <path d="M14 15a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v4a1 1 0 0 1-1 1h-4a1 1 0 0 1-1-1z"/>
      <path d="M14 5a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v4a1 1 0 0 1-1 1h-4a1 1 0 0 1-1-1z"/>
      <path d="M10 7h4"/>
      <path d="M7 10v5a1 1 0 0 0 1 1h6"/>
    </svg>`;
  }

  function render() {
    const userInitial = userName.charAt(0).toUpperCase();

    // Collapsed state — show only expand button
    if (isCollapsed) {
      el.style.width = '48px';
      el.innerHTML = `
        <div style="height:100%; display:flex; flex-direction:column; align-items:center; padding-top:12px; background:var(--task-sidebar-bg);">
          <button class="expand-btn" style="width:40px; height:40px; display:flex; align-items:center; justify-content:center; border-radius:8px; border:none; background:transparent; cursor:pointer; transform:rotate(180deg);">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--task-text)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m11 17-5-5 5-5"/>
              <path d="M18 17V7"/>
            </svg>
          </button>
        </div>`;
      el.querySelector('.expand-btn').onclick = () => {
        isCollapsed = false;
        render();
      };
      return;
    }

    // Expanded state
    el.style.width = '251px';

    // Filter store items by search query
    const filtered = storeSections
      .map((s) => ({
        ...s,
        items: s.items.filter((id) => {
          const item = storeItems.find((si) => si.id === id);
          return item?.name.toLowerCase().includes(searchQuery.toLowerCase());
        }),
      }))
      .filter((s) => s.items.length > 0);

    // Build section HTML
    const sectionsHtml = filtered
      .map((section) => {
        const itemsHtml = section.items
          .map((itemId) => {
            const item = storeItems.find((si) => si.id === itemId);
            const isSelected = itemId === selectedStoreId;
            const bgColor = isSelected ? 'rgb(1,108,221)' : 'transparent';
            const textColor = isSelected ? 'rgb(254,255,255)' : 'var(--task-text)';
            const iconColor = isSelected ? 'rgb(254,255,255)' : 'var(--task-text)';

            return `
              <button class="list-item" data-id="${itemId}"
                style="display:flex; align-items:center; gap:8px; padding:0 8px; height:32px;
                       border-radius:8px; border:none; cursor:pointer; text-align:left;
                       background:${bgColor}; font-family:Inter,sans-serif;">
                ${schemaIcon(iconColor)}
                <span style="font-size:12px; color:${textColor};">${item.name}</span>
              </button>`;
          })
          .join('');

        return `
          <div style="display:flex; flex-direction:column; gap:2px;">
            <div style="padding:8px; font-size:12px; color:var(--task-text);">${section.header}</div>
            ${itemsHtml}
          </div>`;
      })
      .join('');

    el.innerHTML = `
      <div style="height:100%; display:flex; flex-direction:column; background:var(--task-sidebar-bg); font-family:Inter,sans-serif;">
        <!-- Header row -->
        <div style="display:flex; align-items:center; justify-content:space-between; padding:12px 16px; height:48px; flex-shrink:0;">
          <div style="display:flex; align-items:center; gap:8px;">
            <div style="width:16px; height:16px; border-radius:4px; background:rgb(245,93,103); display:flex; align-items:center; justify-content:center;">
              <span style="font-family:Urbanist,sans-serif; font-size:11px; font-weight:700; color:var(--task-text);">${userInitial}</span>
            </div>
            <span style="font-family:Urbanist,sans-serif; font-size:14px; color:var(--task-text);">Todo</span>
          </div>
          <button class="collapse-btn" style="width:24px; height:24px; display:flex; align-items:center; justify-content:center; border-radius:4px; border:none; background:transparent; cursor:pointer;">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--task-text)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <path d="m11 17-5-5 5-5"/>
              <path d="M18 17V7"/>
            </svg>
          </button>
        </div>

        <!-- Search and store list -->
        <div style="display:flex; flex-direction:column; gap:8px; padding:12px; flex:1; overflow-y:auto;">
          <div style="display:flex; align-items:center; gap:8px; padding:0 8px; height:32px; border-radius:8px; border:1px solid var(--task-border);">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="var(--task-text)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
              <circle cx="11" cy="11" r="8"/>
              <path d="m21 21-4.3-4.3"/>
            </svg>
            <input class="search"
              style="flex:1; background:transparent; border:none; outline:none; font-size:12px; color:var(--task-text); font-family:Inter,sans-serif;"
              placeholder="Search Lists"
              value="${searchQuery}" />
          </div>
          ${sectionsHtml}
        </div>
      </div>`;

    // Attach event listeners
    el.querySelector('.search').oninput = (e) => {
      searchQuery = e.target.value;
      render();
    };
    el.querySelector('.collapse-btn').onclick = () => {
      isCollapsed = true;
      render();
    };
    el.querySelectorAll('.list-item').forEach((btn) => {
      btn.onclick = () => {
        selectedStoreId = btn.dataset.id;
        if (onSelectStore) onSelectStore(selectedStoreId);
        render();
      };
    });
  }

  render();
  container.appendChild(el);

  return {
    el,
    destroy() {
      el.remove();
    },
  };
}

documentCanvasContent:
/**
 * Document Canvas Component
 *
 * Layout: full-screen with Header (top-right) and editor area (full).
 */

import { createHeader } from '../header/header.js';

/**
 * Create the document canvas layout
 * @param {HTMLElement} container - Container to append to
 * @returns {Object} - Component API with editorContainer and destroy
 */
export function createDocumentCanvas(container) {
  const root = document.createElement('div');
  root.className = 'w-full h-screen relative';

  // Header (absolute top-right)
  const headerInstance = createHeader(root);

  // Editor area — the mind map editor mounts into editorContainer later
  const editorContainer = document.createElement('div');
  editorContainer.style.cssText = 'position: relative; width: 100%; height: 100%; overflow: hidden;';
  root.appendChild(editorContainer);

  container.appendChild(root);

  return {
    el: root,
    editorContainer,
    destroy() {
      if (headerInstance && headerInstance.destroy) headerInstance.destroy();
      root.remove();
    },
  };
}

headerContent:
/**
 * Header Component
 *
 * Absolute positioned top-right with ThemeToggle + VeltTools.
 */

import { createVeltTools } from '../velt/velt-tools.js';
import { createThemeToggle } from './theme-toggle.js';

export function createHeader(container) {
  const header = document.createElement('div');
  header.className = 'absolute top-2 right-6 flex items-center gap-[6px] z-50';

  const themeToggle = createThemeToggle(header);
  const veltTools = createVeltTools(header);

  container.appendChild(header);

  return {
    el: header,
    destroy() {
      if (themeToggle && themeToggle.destroy) themeToggle.destroy();
      if (veltTools && veltTools.destroy) veltTools.destroy();
      header.remove();
    },
  };
}

themeToggleContent:
/**
 * Theme Toggle Component
 *
 * Theme Toggle Component
 *
 * Toggles between light, dark, and system theme modes.
 * Pill-shaped toggle with light/dark/system options.
 */

import { getTheme, setTheme, subscribeToTheme } from '../../lib/theme.js';

const sunIconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
  <circle cx="12" cy="12" r="5" />
  <path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42" />
</svg>`;

const moonIconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
  <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
</svg>`;

const monitorIconSvg = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
  <rect x="2" y="3" width="20" height="14" rx="2" ry="2" />
  <line x1="8" y1="21" x2="16" y2="21" />
  <line x1="12" y1="17" x2="12" y2="21" />
</svg>`;

const options = [
  { value: 'light', icon: sunIconSvg, label: 'Light' },
  { value: 'dark', icon: moonIconSvg, label: 'Dark' },
  { value: 'system', icon: monitorIconSvg, label: 'System' },
];

/**
 * Create theme toggle component
 * @param {HTMLElement} container - Container element to append to
 * @returns {Object} - Component API with el and destroy methods
 */
export function createThemeToggle(container) {
  const wrapper = document.createElement('div');
  Object.assign(wrapper.style, {
    display: 'flex',
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: 'var(--app-surface)',
    borderRadius: '8px',
    padding: '2px',
    gap: '2px',
  });

  const buttons = [];

  options.forEach((opt) => {
    const button = document.createElement('button');
    Object.assign(button.style, {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: '32px',
      height: '28px',
      borderRadius: '6px',
      border: 'none',
      cursor: 'pointer',
      transition: 'background-color 0.15s, color 0.15s',
    });
    button.title = opt.label;
    button.innerHTML = opt.icon;

    button.addEventListener('click', () => setTheme(opt.value));

    buttons.push({ button, value: opt.value });
    wrapper.appendChild(button);
  });

  function updateButtons() {
    const currentTheme = getTheme();
    buttons.forEach(({ button, value }) => {
      const isActive = currentTheme === value;
      button.style.backgroundColor = isActive ? 'var(--app-toggle-active-bg)' : 'transparent';
      button.style.color = isActive ? 'var(--app-text-primary)' : 'var(--app-text-tertiary)';
    });
  }

  // Initial update
  updateButtons();

  // Subscribe to theme changes
  const unsubscribe = subscribeToTheme(() => updateButtons());

  container.appendChild(wrapper);

  return {
    el: wrapper,
    destroy() {
      unsubscribe();
      wrapper.remove();
    },
  };
}

veltCollaborationContent:
/**
 * Velt Collaboration Component
 *
 * Creates Velt comments and sidebar web components.
 */

import { getVeltClient } from '../../lib/velt.js';
import { subscribeToUser } from '../../lib/user.js';

/**
 * Create Velt collaboration components (comments, sidebar)
 * @param {HTMLElement} container - Container element to append to
 * @returns {Object} - Component API with el and destroy methods
 */
export function createVeltCollaboration(container) {
  // Create wrapper for Velt components
  const wrapper = document.createElement('div');
  wrapper.id = 'velt-collaboration';

  // [Velt] Create Velt Comments component with popover mode for mind-map
  const comments = document.createElement('velt-comments');
  comments.setAttribute('text-mode', 'false');
  comments.setAttribute('shadow-dom', 'false');
  comments.setAttribute('popover-mode', 'true');
  comments.setAttribute('popover-triangle-component', 'false');
  comments.setAttribute('comment-pin-highlighter', 'false');
  comments.setAttribute('dialog-on-hover', 'false');
  wrapper.appendChild(comments);

  // [Velt] Create Velt Comments Sidebar
  const sidebar = document.createElement('velt-comments-sidebar');
  wrapper.appendChild(sidebar);

  container.appendChild(wrapper);

  // Subscribe to user changes to handle sign out
  const unsubscribe = subscribeToUser((user, isLoggedIn) => {
    const client = getVeltClient();
    if (isLoggedIn === false && client) {
      client.signOutUser();
    }
  });

  return {
    el: wrapper,
    destroy() {
      unsubscribe();
      wrapper.remove();
    },
  };
}

veltToolsContent:
/**
 * Velt Tools Component
 *
 * Velt Tools Component
 *
 * Creates Velt tool web components (presence, sidebar button, notifications, huddle).
 */

/**
 * Create Velt tool components
 * @param {HTMLElement} container - Container element to append to
 * @returns {Object} - Component API with el and destroy methods
 */
export function createVeltTools(container) {
  // Create wrapper for Velt tools
  const wrapper = document.createElement('div');
  wrapper.className = 'flex items-center gap-2';

  // [Velt] Show online users
  const presence = document.createElement('velt-presence');
  wrapper.appendChild(presence);

  // [Velt] Toggle comments sidebar
  const sidebarButton = document.createElement('velt-sidebar-button');
  wrapper.appendChild(sidebarButton);

  // [Velt] Video call tool
  const huddleTool = document.createElement('velt-huddle-tool');
  huddleTool.setAttribute('type', 'all');
  wrapper.appendChild(huddleTool);

  // [Velt] Notifications panel
  const notificationsTool = document.createElement('velt-notifications-tool');
  notificationsTool.setAttribute('settings', 'true');
  notificationsTool.setAttribute('shadow-dom', 'false');
  wrapper.appendChild(notificationsTool);

  container.appendChild(wrapper);

  return {
    el: wrapper,
    destroy() {
      wrapper.remove();
    },
  };
}

/**
 * Configure notifications tool settings
 * Call this after Velt client is initialized.
 * @param {Object} veltClient - Velt client instance
 */
export function configureNotificationsTool(veltClient) {
  if (!veltClient) return;

  try {
    const notificationElement = veltClient.getNotificationElement();
    if (notificationElement) {
      notificationElement.setTabConfig({
        forYou: { name: 'For You', enable: true },
        documents: { name: 'Payrolls', enable: true },
        all: { name: 'All', enable: true },
      });
    }
  } catch (error) {
    console.warn('[VeltTools] Failed to configure notifications:', error);
  }
}

