    --task-connector: rgb(200, 200, 200);
  }
}

@layer base {
  * {
    @apply border-border;
  }
  html, body, #app {
    height: 100%;
    margin: 0;
    padding: 0;
  }
  body {
    @apply bg-background text-foreground;
  }
}

/* Mind Map Node */
.mindmap-node {
  position: relative;
  background: var(--task-surface);
  border: 1px solid var(--task-border);
  border-radius: 12px;
  padding: 12px 16px;
  font-family: 'Inter', sans-serif;
  font-size: 16px;
  font-weight: 400;
  color: var(--task-text);
  cursor: pointer;
  transition: box-shadow 0.15s ease;
  white-space: nowrap;
  user-select: none;
  display: flex;
  align-items: center;
  gap: 4px;
}
.mindmap-node:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}
.mindmap-node:hover .mindmap-hover-btn {
  opacity: 1;
}

/* Helper Text Animation */
@keyframes pulse-subtle {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.7;
  }
}

.animate-pulse-subtle {
  animation: pulse-subtle 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
